const listRuns = `-- name: ListRuns :many
SELECT r.id, r.organization_id, r.project_id, r.number, r.status, r.trigger, r.ref, r.commit_sha, r.title, r.actor_name, r.created_by, r.rerun_of, r.definition, r.problems, r.variables, r.started_at, r.finished_at, r.created_at, r.updated_at, r.committed_at, coalesce(u.display_name, '')::text AS created_by_name
FROM pipeline_runs r
LEFT JOIN users u ON u.id = r.created_by
WHERE r.project_id = $1
  AND ($2::run_status IS NULL OR r.status = $2::run_status)
  AND ($3::run_trigger IS NULL OR r.trigger = $3::run_trigger)
  AND ($4::text IS NULL OR r.ref = $4::text)
  AND ($5::timestamptz IS NULL
       OR (r.created_at, r.id) < ($5::timestamptz, $6::uuid))
ORDER BY r.created_at DESC, r.id DESC
LIMIT $7
`

type ListRunsParams struct {
	ProjectID uuid.UUID   `json:"project_id"`
	Status    *RunStatus  `json:"status"`
	Trigger   *RunTrigger `json:"trigger"`
	Ref       *string     `json:"ref"`
	CursorAt  *time.Time  `json:"cursor_at"`
	CursorID  *uuid.UUID  `json:"cursor_id"`
	PageSize  int32       `json:"page_size"`
}

type ListRunsRow struct {
	ID             uuid.UUID  `json:"id"`
	OrganizationID uuid.UUID  `json:"organization_id"`
	ProjectID      uuid.UUID  `json:"project_id"`
	Number         int32      `json:"number"`
	Status         RunStatus  `json:"status"`
	Trigger        RunTrigger `json:"trigger"`
	Ref            string     `json:"ref"`
	CommitSha      string     `json:"commit_sha"`
	Title          string     `json:"title"`
	ActorName      string     `json:"actor_name"`
	CreatedBy      *uuid.UUID `json:"created_by"`
	RerunOf        *uuid.UUID `json:"rerun_of"`
	Definition     []byte     `json:"definition"`
	Problems       []byte     `json:"problems"`
	Variables      []byte     `json:"variables"`
	StartedAt      *time.Time `json:"started_at"`
	FinishedAt     *time.Time `json:"finished_at"`
	CreatedAt      time.Time  `json:"created_at"`
	UpdatedAt      time.Time  `json:"updated_at"`
	CommittedAt    *time.Time `json:"committed_at"`
	CreatedByName  string     `json:"created_by_name"`
}

func (q *Queries) ListRuns(ctx context.Context, arg ListRunsParams) ([]ListRunsRow, error) {
	rows, err := q.db.Query(ctx, listRuns,
		arg.ProjectID,
		arg.Status,
		arg.Trigger,
		arg.Ref,
		arg.CursorAt,
		arg.CursorID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListRunsRow{}
	for rows.Next() {
		var i ListRunsRow
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.ProjectID,
			&i.Number,
			&i.Status,
			&i.Trigger,
			&i.Ref,
			&i.CommitSha,
			&i.Title,
			&i.ActorName,
			&i.CreatedBy,
			&i.RerunOf,
			&i.Definition,
			&i.Problems,
			&i.Variables,
			&i.StartedAt,
			&i.FinishedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CommittedAt,
			&i.CreatedByName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

