const nextRunNumber = `-- name: NextRunNumber :one
UPDATE projects SET last_run_number = last_run_number + 1 WHERE id = $1 RETURNING last_run_number
`

// Serializes run creation per project (row lock on the project).
func (q *Queries) NextRunNumber(ctx context.Context, id uuid.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, nextRunNumber, id)
	var last_run_number int32
	err := row.Scan(&last_run_number)
	return last_run_number, err
}

const recentRunExists = `-- name: RecentRunExists :one
SELECT EXISTS (
  SELECT 1 FROM pipeline_runs
  WHERE project_id = $1 AND trigger = $2 AND ref = $3 AND commit_sha = $4
    AND rerun_of IS NULL AND created_at > now() - interval '1 hour'
)
`

type RecentRunExistsParams struct {
	ProjectID uuid.UUID  `json:"project_id"`
	Trigger   RunTrigger `json:"trigger"`
	Ref       string     `json:"ref"`
	CommitSha string     `json:"commit_sha"`
}

// Guards against creating a second run for the same event when a worker is retried.
func (q *Queries) RecentRunExists(ctx context.Context, arg RecentRunExistsParams) (bool, error) {
	row := q.db.QueryRow(ctx, recentRunExists,
		arg.ProjectID,
		arg.Trigger,
		arg.Ref,
		arg.CommitSha,
	)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const setJobStatus = `-- name: SetJobStatus :exec
UPDATE pipeline_jobs SET
  status = $1,
  failure_reason = $2,
  exit_code = $3,
  queued_at = CASE WHEN $1 = 'queued'::job_status THEN now() ELSE queued_at END,
  started_at = CASE WHEN $1 = 'running'::job_status THEN now() ELSE started_at END,
  finished_at = CASE WHEN $1 IN ('succeeded', 'failed', 'canceled', 'skipped') THEN now() ELSE finished_at END
WHERE id = $4
`

type SetJobStatusParams struct {
	Status        JobStatus `json:"status"`
	FailureReason *string   `json:"failure_reason"`
	ExitCode      *int32    `json:"exit_code"`
	ID            uuid.UUID `json:"id"`
}

func (q *Queries) SetJobStatus(ctx context.Context, arg SetJobStatusParams) error {
	_, err := q.db.Exec(ctx, setJobStatus,
		arg.Status,
		arg.FailureReason,
		arg.ExitCode,
		arg.ID,
	)
	return err
}

