const updateStep = `-- name: UpdateStep :execrows
UPDATE job_steps SET
  status = $1,
  exit_code = $2,
  started_at = CASE WHEN $1 = 'running'::step_status THEN coalesce(started_at, now()) ELSE started_at END,
  finished_at = CASE WHEN $1 IN ('succeeded', 'failed', 'skipped', 'canceled') THEN now() ELSE finished_at END
WHERE job_id = $3 AND index = $4
`

type UpdateStepParams struct {
	Status   StepStatus `json:"status"`
	ExitCode *int32     `json:"exit_code"`
	JobID    uuid.UUID  `json:"job_id"`
	Index    int32      `json:"index"`
}

func (q *Queries) UpdateStep(ctx context.Context, arg UpdateStepParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateStep,
		arg.Status,
		arg.ExitCode,
		arg.JobID,
		arg.Index,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertSchedule = `-- name: UpsertSchedule :exec
INSERT INTO pipeline_schedules (project_id, cron, next_run_at) VALUES ($1, $2, $3)
ON CONFLICT (project_id, cron) DO NOTHING
`

type UpsertScheduleParams struct {
	ProjectID uuid.UUID `json:"project_id"`
	Cron      string    `json:"cron"`
	NextRunAt time.Time `json:"next_run_at"`
}

func (q *Queries) UpsertSchedule(ctx context.Context, arg UpsertScheduleParams) error {
	_, err := q.db.Exec(ctx, upsertSchedule, arg.ProjectID, arg.Cron, arg.NextRunAt)
	return err
}
